function show(button,pin=false){const value=terms[button.dataset.legalTerm];if(!value)return;if(active&&active!==button)close();active=button;pinned=pin||pinned;tip.innerHTML=`<strong>${esc(button.dataset.legalTerm)}</strong><p>${esc(value.text)}</p><small>${esc(value.basis)}</small>`;tip.hidden=false;button.setAttribute('aria-describedby',tip.id);const r=button.getBoundingClientRect(),w=Math.min(360,innerWidth-24);tip.style.width=w+'px';tip.style.left=Math.max(12,Math.min(r.left,innerWidth-w-12))+'px';const h=tip.offsetHeight;tip.style.top=Math.max(8,r.bottom+h+14<innerHeight?r.bottom+8:r.top-h-8)+'px';}
document.addEventListener('click',e=>{const b=e.target.closest('.legal-term');if(b){e.preventDefault();if(active===b&&pinned)close();else show(b,true);}else if(!tip.contains(e.target))close();});
