function enhance(){const app=document.querySelector('#app');if(!app)return;const walker=document.createTreeWalker(app,NodeFilter.SHOW_TEXT,{acceptNode(n){return n.parentElement.closest('p, li, .faq-answer')&&!n.parentElement.closest('a,button,summary,script,style,textarea,input,select,.faq-basis,.legal-term-tip')?NodeFilter.FILTER_ACCEPT:NodeFilter.FILTER_REJECT}}),nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const n of nodes){pattern.lastIndex=0;const text=n.textContent,matches=[...text.matchAll(pattern)];if(!matches.length)continue;const frag=document.createDocumentFragment();let pos=0;for(const m of matches){frag.append(text.slice(pos,m.index));const b=document.createElement('button');b.type='button';b.className='legal-term';b.dataset.legalTerm=canonical.get(m[0].toLowerCase());b.textContent=m[0];b.setAttribute('aria-label',m[0]+': definition');b.id='legal-term-'+(++serial);frag.append(b);pos=m.index+m[0].length;}frag.append(text.slice(pos));n.replaceWith(frag);}}
